<section class="admin-panel admin-catalogue"><header class="admin-panel-heading"><h2>All research</h2></header><form class="inline-form admin-catalogue-search" method="get"><input type="hidden" name="tab" value="catalogue"><?php field('Search title or ID','q',(string)($_GET['q']??'')); ?><button>Find requests</button></form>
<div class="table-wrap"><table><thead><tr><th>Research</th><th>Moderation / status</th><th>Added / activity</th><th>Usage</th><th>Actions</th></tr></thead><tbody>
<?php $q=(string)($_GET['q']??''); $page=max(1,(int)($_GET['page']??1)); $offset=($page-1)*50; $total=(int)one('SELECT COUNT(*) n FROM research WHERE title LIKE ? OR id=?',['%'.$q.'%',$q])['n']; $researchRows=all('SELECT r.* FROM research r WHERE r.title LIKE ? OR r.id=? ORDER BY r.created_at DESC LIMIT 50 OFFSET '.$offset,['%'.$q.'%',$q]); $usage=admin_research_usage(array_column($researchRows,'id')); foreach($researchRows as $r): $u=$usage[$r['id']]; ?><tr><td><a href="/admin/research/<?=e($r['id'])?>"><?=e($r['title'])?></a></td><td><?=e($r['moderation'])?><br><?=e($r['status'])?><br><span class="fine">Discovery: <?=!empty($r['discovery_listed'])?'Listed':'Unlisted'?></span></td><td><?=e(substr($r['created_at'],0,10))?><br><?=e(substr($r['activity_at'],0,10))?></td><td data-research-usage="<?=e($r['id'])?>"><details><summary class="text-action">Workflow: <?=e($u['workflow_total'])?> packets</summary><p class="fine"><?=e(admin_usage_breakdown($u['admission']))?><br>Visibility: <?=e(admin_usage_breakdown($u['visibility']))?><br>Workflow admission does not establish scientific correctness.</p></details><details><summary class="text-action">Supplementary: <?=e($u['supplementary_total'])?> contributions</summary><p class="fine"><?=e(admin_usage_breakdown($u['moderation']))?></p></details></td><td><a href="/admin/research/<?=e($r['id'])?>">Manage</a><?php if($r['moderation']==='Approved'&&$r['status']!=='Withdrawn'): ?> · <a href="/research/<?=e($r['slug'])?>">Public page</a><?php endif ?></td></tr><?php endforeach ?></tbody></table></div><nav class="pagination" aria-label="Admin research pages"><?php for($p=1;$p<=ceil($total/50);$p++): ?><a href="/admin?<?=e(http_build_query(['tab'=>'catalogue','q'=>$q,'page'=>$p]))?>"><?=$p?></a><?php endfor ?></nav></section>
